// Core tests: the 14 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC's tests section. Every expected value below was computed by hand
// from the SPEC's rules (integer arithmetic, roundHalfUp, the pinned
// rounding chain).

import assert from "node:assert/strict";
import test from "node:test";
import { buildCoreInput, formatMoney, run } from "../public/js/core/car-depreciation.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const decliningBase = {
  method: "declining",
  price: "100000",
  years: "3",
  salvagePercent: "10",
  rate: "15",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("method: the three methods are valid; anything else is ENUM, empty is EMPTY, a 10-unit method is INPUT_LIMIT", () => {
  assert.equal(run({ ...decliningBase }).ok, true);
  const { rate: _rate, ...noRateBase } = decliningBase;
  assert.equal(run({ ...noRateBase, method: "straight", usefulLife: "10" }).ok, true);
  assert.equal(run({ ...noRateBase, method: "table", tableRates: "20" }).ok, true);
  assert.deepEqual(errorOf({ ...decliningBase, method: "decline" }), {
    code: "ENUM",
    field: "method",
    row: null,
  });
  assert.deepEqual(errorOf({ ...decliningBase, method: "" }), {
    code: "EMPTY",
    field: "method",
    row: null,
  });
  assert.deepEqual(errorOf({ ...decliningBase, method: "decliningx" }), {
    code: "INPUT_LIMIT",
    field: "method",
    row: null,
  });
});

test("price: 1 and 999999999 are valid; 0 is RANGE; 10 units is INPUT_LIMIT; 01 and 1.5 are INTEGER_FORMAT", () => {
  assert.equal(run({ ...decliningBase, price: "1" }).ok, true);
  assert.equal(run({ ...decliningBase, price: "999999999" }).ok, true);
  assert.deepEqual(errorOf({ ...decliningBase, price: "0" }), {
    code: "RANGE",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...decliningBase, price: "1000000000" }), {
    code: "INPUT_LIMIT",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...decliningBase, price: "01" }), {
    code: "INTEGER_FORMAT",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...decliningBase, price: "1.5" }), {
    code: "INTEGER_FORMAT",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...decliningBase, price: " 100" }), {
    code: "INTEGER_FORMAT",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...decliningBase, price: "１００" }), {
    code: "INTEGER_FORMAT",
    field: "price",
    row: null,
  });
});

