test("an empty field is EMPTY; a lone surrogate is UNICODE", () => {
  assert.deepEqual(errorOf({ ...decliningBase, price: "" }), {
    code: "EMPTY",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...decliningBase, rate: "\uD800" }), {
    code: "UNICODE",
    field: "rate",
    row: null,
  });
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ ...decliningBase, price: "0", rate: "1.234" }), {
    code: "RANGE",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...decliningBase, method: "bogus", price: "0" }), {
    code: "ENUM",
    field: "method",
    row: null,
  });
  assert.deepEqual(errorOf({ ...decliningBase, years: "31", rate: "1.234" }), {
    code: "RANGE",
    field: "years",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, and accessor are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...decliningBase, extra: "1" }), schema);
  const missing = { ...decliningBase };
  delete missing.price;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...decliningBase, price: 100000 }), schema);
  assert.deepEqual(errorOf(["100000"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("100000"), schema);
  const withGetter = { ...decliningBase };
  Object.defineProperty(withGetter, "price", {
    enumerable: true,
    get() {
      return "100000";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
});

test("schema: another method's field present, or the own method's field missing, is SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...decliningBase, usefulLife: "10" }), schema);
  assert.deepEqual(errorOf({ ...decliningBase, tableRates: "20" }), schema);
  const { rate, ...noRate } = decliningBase;
  assert.deepEqual(errorOf(noRate), schema);
  const straightBase = {
    method: "straight",
    price: "100000",
    years: "3",
    salvagePercent: "10",
    usefulLife: "10",
  };
  assert.deepEqual(errorOf({ ...straightBase, rate: "15" }), schema);
  const { usefulLife, ...noLife } = straightBase;
  assert.deepEqual(errorOf(noLife), schema);
});

test("tableRates: 30 rows are valid; 31 rows are ROW_LIMIT; a middle empty row is DECIMAL_FORMAT with its row; a trailing LF is fine", () => {
  const tableBase = {
    method: "table",
    price: "100000",
    years: "2",
    salvagePercent: "10",
    tableRates: "20\n18",
  };
  const thirty = Array.from({ length: 30 }, () => "10").join("\n");
  assert.equal(run({ ...tableBase, tableRates: thirty }).ok, true);
  const thirtyOne = Array.from({ length: 31 }, () => "10").join("\n");
  assert.deepEqual(errorOf({ ...tableBase, tableRates: thirtyOne }), {
    code: "ROW_LIMIT",
    field: "tableRates",
    row: null,
  });
  assert.deepEqual(errorOf({ ...tableBase, tableRates: "20\n\n18" }), {
    code: "DECIMAL_FORMAT",
    field: "tableRates",
    row: 2,
  });
  assert.deepEqual(errorOf({ ...tableBase, tableRates: "20\n95\nx" }), {
    code: "DECIMAL_FORMAT",
    field: "tableRates",
    row: 3,
  });
  assert.equal(run({ ...tableBase, tableRates: "20\n18\n" }).ok, true);
  assert.deepEqual(errorOf({ ...tableBase, tableRates: "" }), {
    code: "EMPTY",
    field: "tableRates",
    row: null,
  });
  const overLimit = "9".repeat(260);
  assert.deepEqual(errorOf({ ...tableBase, tableRates: overLimit }), {
    code: "INPUT_LIMIT",
    field: "tableRates",
    row: null,
  });
});

test("straight line with a non-divisible annual amount rounds half-up once: 100000 over 3 years at floor 0", () => {
  // annualDep = roundHalfUp(100000, 3) = (200000 + 3) / 6 = 33333.
  // Years: 66667, 33334, 1. Total 99999, 99.999% -> ph 10000 -> "100.00".
  assert.deepEqual(
    run({ method: "straight", price: "100000", years: "3", salvagePercent: "0", usefulLife: "3" }),
    {
      ok: true,
      result: {
        method: "straight",
        floorValue: 0,
        currentValue: 1,
        totalDepreciation: 99999,
        totalDepreciationPercent: "100.00",
        floorReachedYear: null,
        schedule: [
          { year: 1, ratePercent: null, depreciation: 33333, endValue: 66667, floored: false },
          { year: 2, ratePercent: null, depreciation: 33333, endValue: 33334, floored: false },
          { year: 3, ratePercent: null, depreciation: 33333, endValue: 1, floored: false },
        ],
      },
    },
  );
});

test("straight line can land exactly on floor 0: year 1 ends at 0 (not floored), year 2 clamps", () => {
  // annualDep = 100000 / 1 = 100000. Year 1 raw 0 = floor -> floored false,
  // floorReachedYear 1. Year 2 raw -100000 < 0 -> floored true, end 0.
  assert.deepEqual(
    run({ method: "straight", price: "100000", years: "2", salvagePercent: "0", usefulLife: "1" }),
    {
      ok: true,
      result: {
        method: "straight",
        floorValue: 0,
        currentValue: 0,
        totalDepreciation: 100000,
        totalDepreciationPercent: "100.00",
        floorReachedYear: 1,
        schedule: [
          { year: 1, ratePercent: null, depreciation: 100000, endValue: 0, floored: false },
          { year: 2, ratePercent: null, depreciation: 0, endValue: 0, floored: true },
        ],
      },
    },
  );
});

test("floor value rounds half-up at an exact .5 boundary: price 5 at salvage 10% gives floor 1", () => {
  // floor = roundHalfUp(5 * 1000, 10000) = (10000 + 10000) / 20000 = 1.
  const outcome = run({
    method: "declining",
    price: "5",
    years: "1",
    salvagePercent: "10",
    rate: "0",
  });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.floorValue, 1);
  assert.equal(outcome.result.currentValue, 5);
  assert.equal(outcome.result.totalDepreciation, 0);
  assert.equal(outcome.result.totalDepreciationPercent, "0.00");
});

test("declining at the largest valid price stays exact", () => {
  const outcome = run({
    method: "declining",
    price: "999999999",
    years: "1",
    salvagePercent: "50",
    rate: "90",
  });
  assert.equal(outcome.ok, true);
  // floor = roundHalfUp(999999999 * 5000, 10000) = 499999999.5 -> 500000000
  // (half-up). raw = roundHalfUp(999999999 * 1000, 10000) = 99999999.9 -> 100000000,
  // below the floor, so it clamps to 500000000.
  assert.equal(outcome.result.floorValue, 500000000);
  assert.equal(outcome.result.currentValue, 500000000);
  assert.equal(outcome.result.totalDepreciation, 499999999);
  assert.equal(outcome.result.totalDepreciationPercent, "50.00");
  assert.equal(outcome.result.floorReachedYear, 1);
  assert.deepEqual(outcome.result.schedule, [
    { year: 1, ratePercent: "90.00", depreciation: 499999999, endValue: 500000000, floored: true },
  ]);
});

test("property: end values never fall below the floor, never increase, and yearly depreciation sums to the total", () => {
  const inputs = [
    { method: "declining", price: "123456", years: "30", salvagePercent: "12.34", rate: "7.89" },
    { method: "straight", price: "987654", years: "30", salvagePercent: "50", usefulLife: "7" },
    {
      method: "table",
      price: "555555",
      years: "30",
      salvagePercent: "0.01",
      tableRates: "90\n0.5\n33.33",
    },
    { method: "declining", price: "1", years: "30", salvagePercent: "0", rate: "90" },
  ];
  for (const input of inputs) {
    const outcome = run(input);
    assert.equal(outcome.ok, true);
    const { result } = outcome;
    let previous = Number(input.price);
    let sum = 0;
    for (const row of result.schedule) {
      assert.ok(row.endValue >= result.floorValue, `end below floor: ${row.endValue}`);
      assert.ok(row.endValue <= previous, `end increased: ${row.endValue}`);
      assert.equal(row.depreciation, previous - row.endValue);
      // floored can only be true when the value was clamped to the floor.
      if (row.floored) assert.equal(row.endValue, result.floorValue);
      sum += row.depreciation;
      previous = row.endValue;
    }
    assert.equal(sum, result.totalDepreciation);
    assert.equal(previous, result.currentValue);
  }
});

test("property: a higher rate never raises the current value; a higher salvage floor never lowers it", () => {
  let previous = Infinity;
  for (const rate of ["0", "10", "25", "50", "90"]) {
    const outcome = run({ ...decliningBase, rate });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.currentValue <= previous);
    previous = outcome.result.currentValue;
  }
  let lowest = -Infinity;
  for (const salvagePercent of ["0", "10", "25", "50"]) {
    const outcome = run({ ...decliningBase, salvagePercent });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.currentValue >= lowest);
    lowest = outcome.result.currentValue;
  }
});

test("buildCoreInput sends exactly the five fields for the draft's method and keeps other drafts out", () => {
  const draft = {
    method: "straight",
    price: "900000",
    years: "6",
    salvagePercent: "10",
    rate: "15",
    usefulLife: "10",
    tableRates: "20\n18",
  };
  assert.deepEqual(buildCoreInput(draft), {
    method: "straight",
    price: "900000",
    years: "6",
    salvagePercent: "10",
    usefulLife: "10",
  });
  assert.deepEqual(buildCoreInput({ ...draft, method: "table" }), {
    method: "table",
    price: "900000",
    years: "6",
    salvagePercent: "10",
    tableRates: "20\n18",
  });
});

test("display formatting: integer NT$ groups thousands with no decimals", () => {
  assert.equal(formatMoney(0), "0");
  assert.equal(formatMoney(5), "5");
  assert.equal(formatMoney(1000), "1,000");
  assert.equal(formatMoney(443705), "443,705");
  assert.equal(formatMoney(999999999), "999,999,999");
});
